int a = 7, b = 2;
cout << a / b;

// Java
int a = 7, b = 2;
System.out.print(a / b);

// C++
for (int i = 0; i < 3; i++) {
  cout << i;
}

// Java
for (int i = 0; i < 3; i++) {
  System.out.print(i);
}

