// C++
int f() {
  static int i = 0;
  return i++;
}
cout << f() << f();

// Java
class Counter {
  static int i = 0;
  static int f() {
    return i++;
  }
}
System.out.print(Counter.f());
System.out.print(Counter.f());

// C++
int a = 1, b = 1;
if (a-- > 0 || ++b > 1) {
  cout << a << b;
}

// Java
int a = 1, b = 1;
if (a-- > 0 || ++b > 1) {
  System.out.print(a + "" + b);
}

// C++
int x = 3;
int y = x++ + ++x;
cout << x << " " << y;

// Java
int x = 3;
int y = x++ + ++x;
System.out.print(x + " " + y);

